window.VF2_UNITS = {"12":{"unit":12,"code":"VF2-U12","title":"ENTERTAINMENT","startNumber":226,"endNumber":238,"entries":[{"number":226,"term":"rehearse (v) · rehearsal (n)","spoken":"rehearse , rehearsal","ipa":"rehearse /riˈhɝːs/ · rehearsal /rɪˈhɝːsəl/","type":"verb · noun · word family","meaning":"tập dượt/diễn tập · buổi/sự tập dượt","definition":"To practise a performance before presenting it; rehearsal is the practice session.","note":"","example":"The actors rehearsed the final scene twice before the evening rehearsal."},{"number":227,"term":"scene (n) · scenery (n) ~ view (n) ~ sight (n)","spoken":"scene , scenery , view , sight","ipa":"scene /siːn/ · scenery /ˈsiːnɚi/ · view /vjuː/ · sight /saɪt/","type":"noun · word family","meaning":"cảnh phim/sân khấu · phong cảnh chung ~ tầm nhìn/cảnh nhìn từ một nơi ~ cảnh vật cụ thể nhìn thấy","definition":"A scene is part of a film or play; scenery is the general landscape; view is what can be seen from a position; sight is a particular thing seen.","note":"scene là cảnh phim/sân khấu; scenery là phong cảnh chung; view là tầm nhìn; sight là cảnh cụ thể.","example":"The scene was filmed in mountain scenery, where the view became the film's most memorable sight."},{"number":228,"term":"orchestra (n) # choir (n)","spoken":"orchestra , choir","ipa":"orchestra /ˈɔːrkəstrə/ · choir /ˈkwaɪɚ/","type":"noun · word family","meaning":"dàn nhạc # dàn hợp xướng","definition":"An orchestra is a large group of instrumentalists; a choir is a group of singers.","note":"orchestra là dàn nhạc; choir là dàn hợp xướng gồm người hát.","example":"The orchestra played below the stage while the choir performed behind the actors."},{"number":229,"term":"fiction (n) · fictional (a)","spoken":"fiction , fictional","ipa":"fiction /ˈfɪkʃən/ · fictional /ˈfɪkʃənəl/","type":"noun · adjective · word family","meaning":"tác phẩm/văn học hư cấu · hư cấu/không có thật","definition":"Stories and characters that are invented rather than factual; fictional is the adjective.","note":"fiction là danh từ không đếm được chỉ tác phẩm hư cấu; fictional là tính từ 'hư cấu'.","example":"The novel is fiction, but its fictional society reflects real political concerns."},{"number":230,"term":"make yourself at home","spoken":"make yourself at home","ipa":"make /meɪk/ · yourself /jɚˈsɛlf/ · home /hoʊm/","type":"phrase / pattern","meaning":"hãy tự nhiên như ở nhà","definition":"A friendly invitation telling a guest to relax as if in their own home.","note":"","example":"Please make yourself at home while I prepare the tickets."},{"number":231,"term":"impress (v) · make an impression on sb · give sb an impression · do an impression of sb","spoken":"impress , make an impression on somebody , give somebody an impression , do an impression of somebody","ipa":"impress /ˌɪˈmprɛs/ · make /meɪk/ · impression /ˌɪˈmprɛʃən/ · give /ɡɪv/","type":"verb · phrase / pattern · word family","meaning":"gây ấn tượng · gây ấn tượng với ai · tạo cho ai một cảm tưởng · nhại/bắt chước ai","definition":"Impress means cause admiration; make or give an impression describes the effect created, while do an impression of somebody means imitate them.","note":"make an impression on = gây ấn tượng; do an impression of sb = nhại/bắt chước ai.","example":"Her performance impressed the audience and made a lasting impression, while the comedian did an impression of a famous actor."},{"number":232,"term":"queue (v,n)","spoken":"queue","ipa":"queue /kjuː/","type":"verb · noun","meaning":"xếp hàng · hàng người hoặc hàng xe đang chờ","definition":"To wait in a line for a service; queue is also the line itself.","note":"","example":"Hundreds of fans queued outside the venue, and the queue stretched around the building."},{"number":233,"term":"be bound to do st","spoken":"be bound to do something","ipa":"bound /baʊnd/","type":"phrase / pattern","meaning":"có khả năng cao sẽ làm gì…","definition":"Certain or very likely to do something.","note":"be bound to V diễn tả khả năng gần như chắc chắn, mạnh hơn may/might.","example":"The sequel is bound to attract attention because the first film was internationally successful."},{"number":234,"term":"vary (v) · a variety of ~ many · variable (a) · invariably (adv)","spoken":"vary , a variety of , many , variable , invariably","ipa":"vary /ˈvɛri/ · variety /vɚˈaɪəti/ · many /ˈmɛni/ · variable /ˈvɛriəbəl/ · invariably /ˌɪˈnvɛriəbli/","type":"verb · adjective · adverb · phrase / pattern · word family","meaning":"thay đổi/khác nhau · nhiều/đa dạng · hay thay đổi · luôn luôn","definition":"To change or differ; variety means many types; variable means changeable; invariably means always.","note":"variable = hay thay đổi; invariably = luôn luôn/không thay đổi. Hai từ cùng gốc nhưng nghĩa đối lập trong ngữ cảnh.","example":"Ticket prices vary, and a variety of discounts is available, but demand is invariably high."},{"number":235,"term":"drop off","spoken":"drop off","ipa":"drop /drɑːp/ · off /ɔːf/","type":"phrasal verb","meaning":"ngủ gật","definition":"To begin sleeping, often unintentionally.","note":"","example":"I dropped off during the slow opening scene but woke before the ending."},{"number":236,"term":"show up # show off","spoken":"show up , show off","ipa":"show /ʃoʊ/ · up /ʌp/ · off /ɔːf/","type":"phrasal verb · word family","meaning":"xuất hiện # khoe khoang/phô trương","definition":"Show up means appear; show off means try to attract admiration.","note":"show up = xuất hiện; show off = khoe khoang/phô trương.","example":"The guest failed to show up, while another performer kept showing off on stage."},{"number":237,"term":"take after ~ resemble","spoken":"take after , resemble","ipa":"take /teɪk/ · after /ˈæftɚ/ · resemble /rɪˈzɛmbəl/","type":"phrasal verb · word family","meaning":"giống về ngoại hình; tính cách (với ai đó trong gia đình)","definition":"To resemble an older family member in appearance or character.","note":"take after thường dùng với người trong gia đình; resemble không cần giới từ và dùng rộng hơn.","example":"She takes after her mother in appearance but resembles her father in personality."},{"number":238,"term":"take off","spoken":"take off","ipa":"take /teɪk/ · off /ɔːf/","type":"phrasal verb","meaning":"- cất cánh - trở nên nổi tiếng/thành công…","definition":"To leave the ground in an aircraft, or to suddenly become successful or popular.","note":"take off có thể là cất cánh, cởi đồ hoặc đột ngột thành công; ngữ cảnh quyết định.","example":"The series took off online shortly after the first episode was released."}],"pronunciationFocus":[{"entryNumber":228,"points":[{"category":"common-error","note":"choir /ˈkwaɪɚ/: bắt đầu bằng /kw/, không phải /tʃ/"}]},{"entryNumber":232,"points":[{"category":"common-error","note":"queue /kjuː/: từ chỉ có một âm tiết"}]},{"entryNumber":233,"points":[{"category":"final-sound","note":"bound /baʊnd/: giữ rõ cụm âm cuối /nd/"}]},{"entryNumber":234,"points":[{"category":"word-stress","note":"variety /vɚˈaɪəti/ và invariably /ˌɪˈnvɛriəbli/ đều nhấn âm tiết thứ hai"}]},{"entryNumber":238,"points":[{"category":"linking","note":"take‿off: nối /k/ sang /ɔː/"}]}]}};
